head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _5 : options(선택) 파라미터 전용 — noDraw/keepMerge/fixedRows/fixedCols + 생략. description 은 _1 과 동일.
//    mergeOptionStr 은 never/bycol/byrow 중 선택(병합 방식 자체 검증은 _1~_4 에서 다룸).
scwin.tData = {
    "description" : "[gridView > M > mergeCells]<br/>GridView 컴포넌트의 mergeCells 속성을 설정합니다.",
    "validation" : [
        "options(선택) 파라미터를 생략하면 기본값(noDraw/keepMerge/fixedRows/fixedCols 모두 false)으로 병합 처리 제어가 동작합니다.",
        "options.noDraw(선택) true 설정 시 GridView 를 갱신하지 않습니다(다회 병합 성능 개선). false(기본) 설정 시 갱신합니다.",
        "options.keepMerge(선택) true 설정 시 고정영역·수동병합 등 기존 병합을 유지합니다. false(기본) 설정 시 기존 병합을 모두 초기화한 후 새로 병합합니다(mergeCellsFixedCols/Rows 속성값은 불변).",
        "options.fixedRows(선택) true 설정 시 fixedRow 고정 영역도 병합 대상이 됩니다(mergeCellsFixedRows 속성값 불변, Body 병합 유지). false(기본) 설정 시 fixedRow 비고정 영역을 대상으로 합니다.",
        "options.fixedCols(선택) true 설정 시 fixedColumn/fixedRightColumn 고정 영역도 병합 대상이 됩니다(mergeCellsFixedCols 속성값 불변, Body 병합 유지). false(기본) 설정 시 비고정 영역을 대상으로 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — options(fixedRows/fixedCols/keepMerge) 차이가 드러나도록 구성.
//  fixedRow=1 (행0 고정 Row), fixedColumn=1 (col1 고정 Column)
//  · 비고정 Body 병합 대상 영역 = col2,col3,col4 / 행1~행4
//
//  행 | col1(고정) | col2 | col3 | col4(번호,포맷)
//  ---+-----------+------+------+-----------------
//   0 |  H        |  H   |  H   |  9
//   1 |  A        |  P   |  P   |  100
//   2 |  A        |  P   |  Q   |  100
//   3 |  B        |  P   |  Q   |  200
//   4 |  B        |  P   |  R   |  200
//
//  · fixedRows=true → fixedRow(행0) 고정 영역도 병합 대상 / fixedCols=true → fixedColumn(col1) 고정 영역도 병합 대상
//  · keepMerge=true → 이전 병합을 유지한 채 추가 병합(byrow 후 bycol 연속 시 누적)
scwin.MERGE_DATA = [
    { "col1": "H", "col2": "H", "col3": "H", "col4": "9" },
    { "col1": "A", "col2": "P", "col3": "P", "col4": "100" },
    { "col1": "A", "col2": "P", "col3": "Q", "col4": "100" },
    { "col1": "B", "col2": "P", "col3": "Q", "col4": "200" },
    { "col1": "B", "col2": "P", "col3": "R", "col4": "200" }
];



// comp 생성 : fixedRow=1, fixedColumn=1 그리드 1개를 동적 생성한다.
//  ★ mergeCells 속성은 생성 attribute 로 주지 않는다. (초기 never 상태로 생성 후 mergeCells() 메소드로 적용)
//  ★ mergeCellsFixedRows/Cols 초기값 "never" → options.fixedRows/fixedCols=true 효과 확인용(속성 불변 입증).
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="fixedRow=1(행0 고정), fixedColumn=1(col1 고정), mergeCellsFixedRows/Cols=never, col4=displayFormat. par_mergeOptionStr + options 선택 후 mergeCells 버튼으로 적용"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // fixedRow=1, fixedColumn=1 + 고정영역 병합 속성 초기값 never
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id,
        fixedRow: 1,
        fixedColumn: 1,
        mergeCellsFixedRows: "never",
        mergeCellsFixedCols: "never"
    });

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="34" id="" style="width:420px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCells sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="col1(고정)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="col4(포맷)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" dataType="number" displayFormat="#,##0.00" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// mergeCells 실행 : par_ 값으로 mergeOptionStr / options 를 구성하여 target1.mergeCells() 호출
//  · mergeOptionStr(필수) : par_mergeOptionStr 선택값
//  · options(선택) : noDraw/keepMerge/fixedRows/fixedCols 중 '미설정'이 아닌 키만 담아 구성.
//    4개 모두 미설정이면 options 인자 자체를 생략하여 target1.mergeCells(mode) 호출(필수여부 N param 생략 로직).
scwin.btn_mergeCells_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let mode = par_mergeOptionStr.getValue();

    // options 구성 : '미설정'(빈 라벨)이 아닌 par_ 값만 boolean 으로 담는다.
    //  · gdl_boolean 의 value 는 위치 인덱스('1'/'2'/'3')이고 의미는 label('','true','false')에 있으므로
    //    getValue() 가 아닌 getText() 로 true/false/미설정(빈 라벨)을 판정한다.
    let vNoDraw    = par_noDraw.getText();
    let vKeepMerge = par_keepMerge.getText();
    let vFixedRows = par_fixedRows.getText();
    let vFixedCols = par_fixedCols.getText();

    let options = {};
    let usedKeys = [];
    if (vNoDraw !== '')    { options.noDraw    = (vNoDraw === 'true');    usedKeys.push("noDraw=" + options.noDraw); }
    if (vKeepMerge !== '') { options.keepMerge = (vKeepMerge === 'true'); usedKeys.push("keepMerge=" + options.keepMerge); }
    if (vFixedRows !== '') { options.fixedRows = (vFixedRows === 'true'); usedKeys.push("fixedRows=" + options.fixedRows); }
    if (vFixedCols !== '') { options.fixedCols = (vFixedCols === 'true'); usedKeys.push("fixedCols=" + options.fixedCols); }

    let hasOptions = usedKeys.length > 0;

    // 필수여부 N 인 options 가 모두 미설정이면 인자 자체를 생략
    if (hasOptions) {
        target1.mergeCells(mode, options);
    } else {
        target1.mergeCells(mode);
    }

    if (options.noDraw === true) {
        bottom.setReturnValue("[옵션] noDraw=true → mergeCells 호출만으로는 화면 미갱신. 화면 갱신은 다음 병합/refresh 시 반영됨.");
    }

    bottom.setReturnValue("[옵션] mergeOptionStr='" + mode + "' / options={" + (hasOptions ? usedKeys.join(", ") : "(생략)") + "}");
    bottom.setReturnValue("[고정영역속성] mergeCellsFixedRows=" + target1.options.mergeCellsFixedRows + " / mergeCellsFixedCols=" + target1.options.mergeCellsFixedCols + " (fixedRows/fixedCols 옵션 사용해도 불변)");

    scwin.printMergeState(bottom);
}



// 병합 상태 확인 : 각 Body td 의 rowSpan/colSpan 을 읽어 세로(⬇)/가로(➡)/블록(⬛) 병합 그룹을 출력
//  - td 셀렉터는 gid = target1.id 사용(e.target.id 는 버튼 id 라 사용 불가)
//  - 흡수되어 표시되지 않는 td 와 중복 키(고정/스크롤 영역 중복 id)는 제외
//  - 고정 영역(행0/col1) td 도 표시되므로 fixedRows/fixedCols 옵션 시 고정 영역 병합도 함께 출력됨
scwin.printMergeState = function (bottom) {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    if (tds.length === 0) {
        bottom.setReturnValue("body cell td 를 찾을 수 없습니다.");
        return;
    }

    let rowSpanCnt = 0;
    let colSpanCnt = 0;
    let descs = [];
    let seen = {};

    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let rs = td.rowSpan || 1;
        let cs = td.colSpan || 1;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);

        let key = r + "_" + c;
        if (seen[key]) continue;
        seen[key] = true;

        if (rs > 1 || cs > 1) {
            if (rs > 1) rowSpanCnt++;
            if (cs > 1) colSpanCnt++;
            let val = (td.textContent || "").trim();
            if (rs > 1 && cs === 1) {
                descs.push("⬇ col" + (c + 1) + " [행" + r + "~행" + (r + rs - 1) + "] 세로병합 = '" + val + "'");
            } else if (cs > 1 && rs === 1) {
                descs.push("➡ 행" + r + " [col" + (c + 1) + "~col" + (c + cs) + "] 가로병합 = '" + val + "'");
            } else {
                descs.push("⬛ [행" + r + "~행" + (r + rs - 1) + ", col" + (c + 1) + "~col" + (c + cs) + "] 블록병합(" + rs + "x" + cs + ") = '" + val + "'");
            }
        }
    }

    let modeName;
    if (rowSpanCnt === 0 && colSpanCnt === 0) modeName = "병합 없음";
    else if (rowSpanCnt > 0 && colSpanCnt === 0) modeName = "세로(rowSpan) 병합";
    else if (colSpanCnt > 0 && rowSpanCnt === 0) modeName = "가로(colSpan) 병합";
    else modeName = "혼합(블록) 병합";

    bottom.setReturnValue("판정 : " + modeName + " / 병합 그룹 " + descs.length + "개");
    if (descs.length === 0) {
        bottom.setReturnValue("병합된 셀 없음");
    } else {
        for (let d = 0; d < descs.length; d++) bottom.setReturnValue(descs[d]);
    }
}
